5	/**
6	 * Derives an owner's {@code checkDigit} = a single Luhn check digit (0-9) computed over the
7	 * digits contained in the owner's customerCode. Non-digit characters are ignored.
8	 */
9	public final class CheckDigit {
10	
11	    private CheckDigit() {
12	    }
13	
14	    public static int of(Owner owner) {
15	        String code = owner.getCustomerCode();
16	        int sum = 0;
17	        boolean dbl = true;
18	        for (int i = code.length() - 1; i >= 0; i--) {
19	            char c = code.charAt(i);
20	            if (c < '0' || c > '9') {
21	                continue;
22	            }
23	            int d = c - '0';
24	            if (dbl) {
25	                d *= 2;
26	                if (d > 9) {
27	                    d -= 9;
28	                }
29	            }
30	            sum += d;
31	            dbl = !dbl;
32	        }
33	        return (10 - (sum % 10)) % 10;
34	    }
35	}
