10	/**
11	 * Derives an owner's {@code identityKey}: the SHA-256 hex digest of normalized telephone + '|' +
12	 * (lower-cased email or empty) + '|' + {@link Soundex} of the last name. Duplicate detection is a
13	 * single equality on this key, so two owners collide only when telephone, email and the phonetic
14	 * last name all match; sharing only a household (different telephones) yields different keys.
15	 */
16	public final class IdentityKey {
17	
18	    private IdentityKey() {
19	    }
20	
21	    public static String of(Owner owner) {
22	        return of(owner.getTelephone(), owner.getEmail(), owner.getLastName());
23	    }
24	
25	    public static String of(String telephone, String email, String lastName) {
26	        String lowerEmail = email == null || email.isBlank() ? "" : email.toLowerCase(Locale.ROOT);
27	        return sha256hex((telephone == null ? "" : telephone) + "|" + lowerEmail + "|" + Soundex.of(lastName));
28	    }
29	
30	    private static String sha256hex(String value) {
31	        try {
32	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
33	            StringBuilder hex = new StringBuilder(digest.length * 2);
34	            for (byte b : digest) {
35	                hex.append(String.format("%02x", b));
36	            }
37	            return hex.toString();
38	        }
39	        catch (NoSuchAlgorithmException e) {
40	            throw new IllegalStateException(e);
41	        }
42	    }
43	}
