21	        String tier = MembershipLevel.of(MembershipPoints.of(owner)) >= 3 ? "PREMIUM" : "STANDARD";
22	        String area = METRO_REGIONS.contains(Locality.of(owner.getCity(), owner.getPostcode())) ? "METRO" : "REGIONAL";
23	        return tier + "_" + area;
24	    }
25	}
