11	/**
12	 * Emits an audit line via the dedicated {@code AUDIT} logger once an owner has been
13	 * created, carrying the owner id, customerCode and registrationDate. Alongside the
14	 * human-readable line it emits an immutable structured {@link OwnerCreatedEvent}.
15	 */
16	public class LogAuditOnCreate {
17	
18	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
19	
20	    private static final AtomicLong SEQUENCE = new AtomicLong();
21	
22	    public void service(@Val Owner owner) {
23	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
24	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
25	            MembershipLevel.of(MembershipPoints.of(owner)),
26	            owner.getCustomerCode() + "-M" + String.format("%02d", FiscalYear.of(owner.getRegistrationDate()) % 100));
27	        AUDIT.info(new OwnerCreatedEvent(SEQUENCE.incrementAndGet(), owner.getId(),
28	            owner.getCustomerCode(), MembershipLevel.of(MembershipPoints.of(owner))).toJson());
29	    }
30	
31	    /**
32	     * Immutable structured owner-created event. Carries the owner's current primary
33	     * identifier: the {@code customerCode} today, and whatever replaces it later (once
34	     * the customerCode is unified into the memberId, that value is carried instead).
35	     */
36	    private record OwnerCreatedEvent(long seq, int ownerId, String customerCode, int membershipLevel) {
37	        String toJson() {
38	            return "{\"seq\":" + seq + ",\"ownerId\":" + ownerId
39	                + ",\"customerCode\":\"" + customerCode + "\""
40	                + ",\"membershipLevel\":" + membershipLevel
41	                + ",\"event\":\"OWNER_CREATED\"}";
42	        }
43	    }
44	}
