7	/**
8	 * Membership points contributed by the owner's tenure exceeding the qualifying threshold
9	 * of one elapsed {@link FiscalYear}. One factor of the overall {@link MembershipPoints}
10	 * total; owns the tenure test, its threshold and its weight. A newly created owner has zero tenure.
11	 */
12	public final class TenureFactor {
13	
14	    private static final int POINTS = 3;
15	
16	    private static final int TENURE_FISCAL_YEARS = 1;
17	
18	    private TenureFactor() {
19	    }
20	
21	    public static int points(Owner owner) {
22	        return qualifies(owner) ? POINTS : 0;
23	    }
24	
25	    private static boolean qualifies(Owner owner) {
26	        LocalDate registered = owner.getRegistrationDate();
27	        return registered != null
28	                && FiscalYear.of(LocalDate.now()) - FiscalYear.of(registered) >= TENURE_FISCAL_YEARS;
29	    }
30	}
