9	/**
10	 * Response-time membership scoring: the entity-derivable {@link MembershipPoints} plus the
11	 * household factor (+2 for a household of 3 or more), which needs the repository to count
12	 * members. Sets both {@code membershipPoints} and the {@link MembershipLevel} mapped from them.
13	 * Mirrors the response-time derivation used for {@link PossibleDuplicate} and {@link BulkSignup}.
14	 */
15	public final class Membership {
16	
17	    private static final int HOUSEHOLD_POINTS = 2;
18	
19	    private static final int HOUSEHOLD_THRESHOLD = 3;
20	
21	    private Membership() {
22	    }
23	
24	    public static void mark(OwnerDto dto, Owner owner, OwnerRepository ownerRepository) {
25	        int points = MembershipPoints.of(owner) + householdPoints(owner, ownerRepository);
26	        dto.setMembershipPoints(points);
27	        dto.setMembershipLevel(HouseholdCeiling.cap(owner, MembershipLevel.of(points), ownerRepository));
28	    }
29	
30	    private static int householdPoints(Owner owner, OwnerRepository ownerRepository) {
31	        String householdId = owner.getHouseholdId();
32	        long members = ownerRepository.findAll().stream()
33	            .filter(other -> Objects.equals(householdId, other.getHouseholdId()))
34	            .count();
35	        return members >= HOUSEHOLD_THRESHOLD ? HOUSEHOLD_POINTS : 0;
36	    }
37	}
