4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
8	
9	/**
10	 * Soft-match rule: an owner that is not a hard duplicate but shares another owner's last name and
11	 * postcode with a different telephone is flagged {@code possibleDuplicate}, with
12	 * {@code possibleDuplicateOf} set to that owner's id. Mirrors the response-time derivation used for
13	 * {@link BulkSignup}, so both the create and fetch responders report the same value.
14	 */
15	public final class PossibleDuplicate {
16	
17	    private PossibleDuplicate() {
18	    }
19	
20	    public static void mark(OwnerDto dto, Owner owner, OwnerRepository ownerRepository) {
21	        Integer matchId = matchingOwnerId(owner, ownerRepository);
22	        dto.setPossibleDuplicate(matchId != null);
23	        dto.setPossibleDuplicateOf(matchId);
24	    }
25	
26	    private static Integer matchingOwnerId(Owner owner, OwnerRepository ownerRepository) {
27	        if (owner.getPostcode() == null) {
28	            return null;
29	        }
30	        String soundex = Soundex.of(owner.getLastName());
31	        String key = IdentityKey.of(owner);
32	        for (Owner other : ownerRepository.findAll()) {
33	            if (!Objects.equals(other.getId(), owner.getId())
34	                    && soundex.equals(Soundex.of(other.getLastName()))
35	                    && owner.getPostcode().equals(other.getPostcode())
36	                    && !key.equals(IdentityKey.of(other))) { // identical identity key => the same person, not a suspected duplicate
37	                return other.getId();
38	            }
39	        }
40	        return null;
41	    }
42	}
