17	
18	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
19	            throws DuplicateIdentityException {
20	        String key = IdentityKey.of(request.getTelephone(), request.getEmail(), request.getLastName());
21	        for (Owner owner : ownerRepository.findAll()) {
22	            if (!owner.isDeleted() && key.equals(IdentityKey.of(owner))) {
23	                throw new DuplicateIdentityException(key);
24	            }
25	        }
26	    }
27	}
